func ReplyError(w http.ResponseWriter, code int, short string, desc string) {

	w.Header().Set("Cache-Control", "no-cache, no-store, must-revalidate")
	w.WriteHeader(code)

	w.Write([]byte(tpl_error.ExecuteString(map[string]interface{}{
		"status_code": strconv.Itoa(code),
		"short":       html.EscapeString(short),
		"desc":        html.EscapeString(desc),
	})))

}

